package com.johnny.hotel.payroll;
import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.entity.SysAuditLog;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.financeexpense.*;import com.johnny.hotel.mapper.*;import com.johnny.hotel.pagination.*;import com.johnny.hotel.payroll.PayrollModels.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.math.*;import java.time.Clock;import java.time.LocalDate;import java.time.LocalDateTime;import java.util.*;
@Service@RequiredArgsConstructor public class PayrollService{
 private final PayrollMapper db;private final PayrollAccess access;private final SysUserMapper users;private final HotelExpenseService expenses;private final BusinessDateService dates;private final SysAuditLogMapper audits;private final PaginationSupport pages;private final Clock clock;
 private LocalDateTime now(){return LocalDateTime.now(clock);}private void need(boolean b,String m){if(!b)throw new BusinessException(409,m);}private String req(String s,String n){need(s!=null&&!s.isBlank(),n+" is required");return s.trim();}private String norm(String s){return s==null||s.isBlank()?null:s.trim().toUpperCase();}private BigDecimal money(BigDecimal v){need(v!=null&&v.signum()>0&&v.scale()<=2,"Invalid amount");return v.setScale(2);}private void event(Long period,Long slip,String type,Long actor){need(db.action(period,slip,type,actor,null)==1,"Payroll history failed");need(audits.insert(SysAuditLog.builder().operatorId(actor).action(type).detail(slip==null?"Payroll period "+period:"Payslip "+slip).build())==1,"Audit failed");}
 @Transactional public Compensation compensation(PayrollCommands.CompensationCreate c){var a=access.actor();access.hr(a);need(c!=null&&c.getEmployeeId()!=null&&db.lockEmployee(c.getEmployeeId())!=null&&users.selectById(c.getEmployeeId())!=null,"Employee not found");String type=norm(c.getPayType());need(Set.of("MONTHLY","HOURLY").contains(type),"Invalid pay type");need(c.getEffectiveFrom()!=null&&(c.getEffectiveTo()==null||!c.getEffectiveTo().isBefore(c.getEffectiveFrom())),"Invalid effective interval");LocalDate end=c.getEffectiveTo()==null?LocalDate.of(9999,12,31):c.getEffectiveTo();need(db.compensationOverlap(c.getEmployeeId(),c.getEffectiveFrom(),end)==0,"Compensation versions overlap");BigDecimal base="MONTHLY".equals(type)?money(c.getBaseAmount()):null,rate="HOURLY".equals(type)?money(c.getHourlyRate()):null;var p=Compensation.builder().employeeId(c.getEmployeeId()).payType(type).currency(req(c.getCurrency(),"currency").toUpperCase()).baseAmount(base).hourlyRate(rate).effectiveFrom(c.getEffectiveFrom()).effectiveTo(c.getEffectiveTo()).status(1).reason(req(c.getReason(),"reason")).createdBy(a.id()).approvedBy(a.id()).approvedAt(now()).build();need(db.insertCompensation(p)==1,"Compensation creation failed");event(null,null,"COMPENSATION_CREATED",a.id());return db.compensation(p.getId());}
 public PageResult<Compensation> compensationHistory(Long employee,Integer page,Integer size){var a=access.actor();if(!a.id().equals(employee))access.hr(a);var w=pages.window(page,size,true);return pages.result(w,db.compensationHistory(employee,w.offset(),pages.limit(w)),db.compensationCount(employee));}
 @Transactional public Compensation deactivateCompensation(Long id){var a=access.actor();access.hr(a);var c=db.compensation(id);need(c!=null,"Compensation not found");if(c.getStatus()==0)return c;need(db.deactivateCompensation(id)==1,"Compensation changed concurrently");event(null,null,"COMPENSATION_CHANGED",a.id());return db.compensation(id);}
 public Policy currentPolicy(){var a=access.actor();need(a.has("HR_ADMIN","FINANCE","OWNER","SUPER_ADMIN"),"Payroll access denied");return db.currentPolicy();}
 @Transactional public Policy policy(PayrollCommands.PolicyWrite c){var a=access.actor();access.hr(a);need(db.lockPayrollScope()!=null,"Payroll scope unavailable");String rounding=norm(c.getRoundingMode());need(Set.of("HALF_UP","HALF_DOWN","HALF_EVEN").contains(rounding),"Invalid rounding mode");if(c.getMonthlyUnpaidMode()!=null){need("STANDARD_DAYS".equals(norm(c.getMonthlyUnpaidMode()))&&c.getStandardDays()!=null&&c.getStandardDays().signum()>0,"Invalid monthly unpaid policy");}if(c.getHourlyPaidLeaveMode()!=null){need("HOURLY_RATE".equals(norm(c.getHourlyPaidLeaveMode()))&&c.getStandardHoursPerDay()!=null&&c.getStandardHoursPerDay().signum()>0,"Invalid hourly paid leave policy");}var p=Policy.builder().versionNo(db.maxPolicyVersion()+1).monthlyUnpaidMode(norm(c.getMonthlyUnpaidMode())).hourlyPaidLeaveMode(norm(c.getHourlyPaidLeaveMode())).standardDays(c.getStandardDays()).standardHoursPerDay(c.getStandardHoursPerDay()).roundingMode(rounding).createdBy(a.id()).activatedBy(a.id()).activatedAt(now()).build();db.deactivatePolicy();need(db.insertPolicy(p)==1,"Policy activation failed");event(null,null,"PAYROLL_POLICY_ACTIVATED",a.id());return p;}
 @Transactional public Period createPeriod(PayrollCommands.PeriodCreate c){var a=access.actor();access.hr(a);need(c.getPeriodStart()!=null&&c.getPeriodEnd()!=null&&c.getPeriodStart().isBefore(c.getPeriodEnd()),"Invalid period");need(c.getEmployeeIds()!=null&&!c.getEmployeeIds().isEmpty(),"Payroll employees are required");need(db.lockPayrollScope()!=null,"Payroll scope unavailable");var old=db.periodByKey(a.id(),req(c.getRequestKey(),"request key"));if(old!=null)return old;need(db.periodOverlap(c.getPeriodStart(),c.getPeriodEnd())==0,"Payroll periods overlap");var policy=db.activePolicy();var p=Period.builder().periodStart(c.getPeriodStart()).periodEnd(c.getPeriodEnd()).currency(req(c.getCurrency(),"currency").toUpperCase()).status(0).policyId(policy==null?null:policy.getId()).createdBy(a.id()).requestKey(c.getRequestKey()).build();need(db.insertPeriod(p)==1,"Period creation failed");for(Long employee:new LinkedHashSet<>(c.getEmployeeIds())){need(users.selectById(employee)!=null,"Employee not found");need(db.addEmployee(p.getId(),employee)==1,"Employee inclusion failed");}event(p.getId(),null,"PAYROLL_PERIOD_CREATED",a.id());return db.period(p.getId());}
 public Period period(Long id){var a=access.actor();need(a.has("HR_ADMIN","FINANCE","OWNER","SUPER_ADMIN"),"Payroll access denied");var p=db.period(id);need(p!=null,"Payroll period not found");return p;}
 @Transactional public Period calculate(Long id){var a=access.actor();access.hr(a);var p=db.lockPeriod(id);need(p!=null&&Set.of(0,1).contains(p.getStatus()),"Payroll is frozen");for(Long employee:db.eligibleEmployees(id))calculateOne(p,employee,a.id());if(p.getStatus()==0)db.calculated(id);event(id,null,"PAYROLL_CALCULATED",a.id());return db.period(id);}
 private void calculateOne(Period p,Long employee,Long actor){var old=db.lockPayslipByEmployee(p.getId(),employee);if(old!=null&&old.getStatus()>=2)return;var comp=db.coveringCompensation(employee,p.getPeriodStart().toLocalDate(),p.getPeriodEnd().minusNanos(1).toLocalDate());var policy=p.getPolicyId()==null?null:db.policy(p.getPolicyId());var att=db.attendance(employee,p.getPeriodStart(),p.getPeriodEnd());var leaves=db.leaves(employee,p.getPeriodStart(),p.getPeriodEnd());BigDecimal paid=leave(leaves,"PAID"),unpaid=leave(leaves,"UNPAID"),base=BigDecimal.ZERO,worked=BigDecimal.ZERO,paidPay=BigDecimal.ZERO,unpaidDed=BigDecimal.ZERO;String blocked=comp==null?"NO_ACTIVE_COMPENSATION_PROFILE":!p.getCurrency().equalsIgnoreCase(comp.getCurrency())?"COMPENSATION_CURRENCY_MISMATCH":db.crossingLeaves(employee,p.getPeriodStart(),p.getPeriodEnd())>0?"LEAVE_CROSSES_PAYROLL_PERIOD":null;RoundingMode round=policy==null?RoundingMode.HALF_UP:RoundingMode.valueOf(policy.getRoundingMode());if(comp!=null&&"MONTHLY".equals(comp.getPayType())){base=comp.getBaseAmount();if(unpaid.signum()>0){if(policy==null||policy.getMonthlyUnpaidMode()==null||policy.getStandardDays()==null)blocked="MISSING_MONTHLY_UNPAID_LEAVE_POLICY";else unpaidDed=base.divide(policy.getStandardDays(),8,round).multiply(days(leaves,"UNPAID",policy));}}if(comp!=null&&"HOURLY".equals(comp.getPayType())){worked=comp.getHourlyRate().multiply(BigDecimal.valueOf(att.getWorkedMinutes()).divide(BigDecimal.valueOf(60),8,round));if(paid.signum()>0){if(policy==null||policy.getHourlyPaidLeaveMode()==null||policy.getStandardHoursPerDay()==null)blocked="MISSING_HOURLY_PAID_LEAVE_POLICY";else paidPay=comp.getHourlyRate().multiply(hours(leaves,"PAID",policy));}}var adjs=old==null?List.<Adjustment>of():db.adjustments(old.getId());BigDecimal allowance=sum(adjs,"ALLOWANCE","ADD"),bonus=sum(adjs,"BONUS","ADD"),deduct=adjs.stream().filter(x->"DEDUCT".equals(x.getDirection())).map(Adjustment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add),other=adjs.stream().filter(x->Set.of("OTHER","REIMBURSEMENT").contains(x.getAdjustmentType())).map(x->"DEDUCT".equals(x.getDirection())?x.getAmount().negate():x.getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add),gross=base.add(worked).add(paidPay).add(allowance).add(bonus).add(other.max(BigDecimal.ZERO)),total=unpaidDed.add(deduct).add(other.min(BigDecimal.ZERO).abs());var s=Payslip.builder().id(old==null?null:old.getId()).payrollPeriodId(p.getId()).employeeId(employee).compensationProfileId(comp==null?null:comp.getId()).status(blocked==null?0:1).blockedReason(blocked).payType(comp==null?null:comp.getPayType()).currency(p.getCurrency()).rateSnapshot(comp==null?null:("MONTHLY".equals(comp.getPayType())?comp.getBaseAmount():comp.getHourlyRate())).workedMinutes(att.getWorkedMinutes()).attendanceSessionCount(att.getSessionCount()).attendanceAnomalyCount(att.getAnomalyCount()).correctionFactCount(att.getCorrectionCount()).paidLeaveAmount(paid).unpaidLeaveAmount(unpaid).leaveSnapshot(leaves.toString()).policySnapshot(policy==null?null:"policy:"+policy.getId()+"/v"+policy.getVersionNo()).basePay(scale(base,round)).attendanceBasedPay(scale(worked,round)).paidLeavePay(scale(paidPay,round)).unpaidLeaveDeduction(scale(unpaidDed,round)).allowances(scale(allowance,round)).bonuses(scale(bonus,round)).manualDeductions(scale(deduct,round)).otherAdjustments(scale(other,round)).grossPay(scale(gross,round)).totalDeductions(scale(total,round)).netPay(scale(gross.subtract(total).max(BigDecimal.ZERO),round)).calculatedAt(now()).build();if(old==null)db.insertPayslip(s);else db.updatePayslip(s);event(p.getId(),s.getId(),blocked==null?"PAYSLIP_CALCULATED":"PAYSLIP_BLOCKED",actor);}
 @Transactional public Adjustment adjustment(Long id,PayrollCommands.AdjustmentCreate c){var a=access.actor();access.hr(a);var s=db.lockPayslip(id);need(s!=null&&s.getStatus()<=1,"Payslip is frozen");var prior=db.adjustmentByKey(id,req(c.getRequestKey(),"request key"));if(prior!=null)return prior;String type=norm(c.getType()),direction=norm(c.getDirection());need(Set.of("BONUS","ALLOWANCE","DEDUCTION","REIMBURSEMENT","OTHER").contains(type)&&Set.of("ADD","DEDUCT").contains(direction),"Invalid adjustment");var x=Adjustment.builder().payslipId(id).adjustmentType(type).direction(direction).amount(money(c.getAmount())).reason(req(c.getReason(),"reason")).createdBy(a.id()).requestKey(c.getRequestKey()).build();need(db.insertAdjustment(x)==1,"Adjustment failed");event(s.getPayrollPeriodId(),id,"ADJUSTMENT_ADDED",a.id());return x;}
 @Transactional public Period approve(Long id){var a=access.actor();access.owner(a);var p=db.lockPeriod(id);need(p!=null&&p.getStatus()==1,"Payroll is not calculated");need(db.blocked(id)==0,"Payroll has blocked payslips");need(!a.id().equals(p.getCreatedBy()),"Payroll creator cannot self-approve");var at=now();need(db.approvePeriod(id,a.id(),at)==1,"Payroll changed concurrently");db.approvePayslips(id,at);event(id,null,"PAYROLL_APPROVED",a.id());return db.period(id);}
 @Transactional public Payslip pay(Long id,PayrollCommands.PaymentConfirm c){var a=access.actor();access.finance(a);var s=db.lockPayslip(id);need(s!=null,"Payslip not found");var existing=db.payment(id);if(existing!=null){need(Objects.equals(existing.getRequestKey(),req(c.getRequestKey(),"request key"))&&Objects.equals(existing.getPaymentMethod(),norm(c.getMethod())),"Payroll payment idempotency conflict");return db.payslip(id);}need(s.getStatus()==2,"Payslip is not approved");need(s.getNetPay()!=null&&s.getNetPay().signum()>0,"Zero payable payslip cannot be paid");var p=db.lockPeriod(s.getPayrollPeriodId());need(p!=null&&p.getStatus()==2&&!Objects.equals(p.getApprovedBy(),a.id()),"Payment requires independent approved payroll");String method=norm(c.getMethod());need(Set.of("BANK_TRANSFER","OTHER").contains(method),"CASH payroll requires an explicit future cash source");LocalDate posting=dates.postingDate();var e=expenses.create(new ExpenseCommands.Create(s.getNetPay(),s.getCurrency(),ExpenseCategory.PAYROLL,"Payroll payslip "+id,"PAYSLIP-"+id,posting,p.getPeriodStart().toLocalDate(),null,null,s.getEmployeeId(),"payroll-expense-"+id),a.id());expenses.submit(e.getId(),new ExpenseCommands.Action("payroll-submit-"+id,"Payroll approved"),a.id());expenses.approve(e.getId(),new ExpenseCommands.Action("payroll-approve-"+id,"Payroll approved"),p.getApprovedBy());e=expenses.pay(e.getId(),new ExpenseCommands.Pay("payroll-pay-"+id,method,c.getExternalReference()),a.id());var payment=Payment.builder().payslipId(id).amount(s.getNetPay()).paymentMethod(method).externalReference(c.getExternalReference()).requestKey(req(c.getRequestKey(),"request key")).paidBy(a.id()).postingBusinessDate(e.getPostingBusinessDate()).paidAt(e.getPaidAt()).expenseId(e.getId()).build();need(db.insertPayment(payment)==1&&db.paidPayslip(id,e.getPaidAt(),e.getId())==1,"Payment changed concurrently");db.paidPeriod(p.getId(),e.getPaidAt());event(p.getId(),id,"PAYROLL_PAYMENT_CONFIRMED",a.id());return db.payslip(id);}
 @Transactional public Period close(Long id){var a=access.actor();access.owner(a);var p=db.lockPeriod(id);need(p!=null&&p.getStatus()==3,"Payroll is not fully paid");need(db.closePeriod(id,now())==1,"Payroll changed concurrently");event(id,null,"PAYROLL_CLOSED",a.id());return db.period(id);}
 public PageResult<Period> periods(Integer page,Integer size){var a=access.actor();need(a.has("HR_ADMIN","FINANCE","OWNER","SUPER_ADMIN"),"Payroll access denied");var w=pages.window(page,size,true);return pages.result(w,db.periods(w.offset(),pages.limit(w)),db.periodCount());}public PageResult<Payslip> payslips(Long period,Integer page,Integer size){var a=access.actor();need(a.has("HR_ADMIN","FINANCE","OWNER","SUPER_ADMIN"),"Payroll access denied");var w=pages.window(page,size,true);var rows=db.payslips(period,w.offset(),pages.limit(w));rows.forEach(this::changed);return pages.result(w,rows,db.payslipCount(period));}public PageResult<Payslip> mine(Integer page,Integer size){var a=access.actor();var w=pages.window(page,size,true);var rows=db.mine(a.id(),w.offset(),pages.limit(w));rows.forEach(this::changed);return pages.result(w,rows,db.mineCount(a.id()));}public Payslip detail(Long id){var a=access.actor();var s=db.payslip(id);need(s!=null,"Payslip not found");if(!a.id().equals(s.getEmployeeId())&&!a.has("HR_ADMIN","FINANCE","OWNER","SUPER_ADMIN"))throw access.denied();if(a.id().equals(s.getEmployeeId()))need(s.getStatus()>=2,"Payslip is not published");changed(s);return s;}
 private void changed(Payslip s){s.setSourceChangeDetected(s.getStatus()>=2&&db.sourceChanges(s.getPayrollPeriodId(),s.getEmployeeId(),s.getCalculatedAt())>0);}private BigDecimal scale(BigDecimal v,RoundingMode r){return v.setScale(2,r);}private BigDecimal leave(List<LeaveInput>x,String treatment){return x.stream().filter(i->treatment.equals(i.getPaidTreatment())).map(LeaveInput::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}private BigDecimal days(List<LeaveInput>x,String t,Policy p){return x.stream().filter(i->t.equals(i.getPaidTreatment())).map(i->"HOUR".equals(i.getUnit())?i.getAmount().divide(p.getStandardHoursPerDay(),8,RoundingMode.HALF_UP):i.getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);}private BigDecimal hours(List<LeaveInput>x,String t,Policy p){return x.stream().filter(i->t.equals(i.getPaidTreatment())).map(i->"HOUR".equals(i.getUnit())?i.getAmount():i.getAmount().multiply(p.getStandardHoursPerDay())).reduce(BigDecimal.ZERO,BigDecimal::add);}private BigDecimal sum(List<Adjustment>x,String t,String d){return x.stream().filter(a->t.equals(a.getAdjustmentType())&&d.equals(a.getDirection())).map(Adjustment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}
}
